const std = @import("std");
pub const Factory = struct {
    allocator: std.mem.Allocator,
    used: []bool,
    random: std.Random,
    remaining: usize = 676000,
    pub fn init(a: std.mem.Allocator, r: std.Random) !Factory {
        const u = try a.alloc(bool, 676000);
        @memset(u, false);
        return .{ .allocator = a, .used = u, .random = r };
    }
    pub fn deinit(f: *Factory) void {
        f.allocator.free(f.used);
    }
    fn allocate(f: *Factory) !usize {
        if (f.remaining == 0) return error.NamesExhausted;
        var i = f.random.uintLessThan(usize, 676000);
        while (f.used[i]) i = (i + 1) % 676000;
        f.used[i] = true;
        f.remaining -= 1;
        return i;
    }
};
pub const Robot = struct {
    factory: *Factory,
    id: ?usize = null,
    pub fn init(f: *Factory) Robot {
        return .{ .factory = f };
    }
    pub fn name(r: *Robot) ![5]u8 {
        if (r.id == null) r.id = try r.factory.allocate();
        const n = r.id.?;
        return .{ @as(u8, @intCast(n / 26000)) + 'A', @as(u8, @intCast((n / 1000) % 26)) + 'A', @as(u8, @intCast((n / 100) % 10)) + '0', @as(u8, @intCast((n / 10) % 10)) + '0', @as(u8, @intCast(n % 10)) + '0' };
    }
    pub fn reset(r: *Robot) void {
        r.id = null;
    }
};

