const std = @import("std");
pub const Factory = struct {
    pub fn init(a: std.mem.Allocator, r: std.Random) !Factory {
        _ = a;
        _ = r;
        return .{};
    }
    pub fn deinit(f: *Factory) void {
        _ = f;
    }
};
pub const Robot = struct {
    pub fn init(f: *Factory) Robot {
        _ = f;
        return .{};
    }
    pub fn name(r: *Robot) ![5]u8 {
        _ = r;
        return "AA000".*;
    }
    pub fn reset(r: *Robot) void {
        _ = r;
    }
};

