// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("robot_name.zig");
test "names format uniqueness retention and reset" {
    var rng = std.Random.DefaultPrng.init(123456);
    var f = try m.Factory.init(t.allocator, rng.random());
    defer f.deinit();
    var r = m.Robot.init(&f);
    const initial = try r.name();
    try t.expectEqualDeep(initial, try r.name());
    r.reset();
    try t.expect(!std.mem.eql(u8, &initial, &(try r.name())));
    var seen = std.AutoHashMap([5]u8, void).init(t.allocator);
    defer seen.deinit();
    for (0..1000) |_| {
        var robot = m.Robot.init(&f);
        const n = try robot.name();
        try t.expect(n[0] >= 'A' and n[0] <= 'Z' and n[1] >= 'A' and n[1] <= 'Z');
        for (n[2..]) |c| try t.expect(c >= '0' and c <= '9');
        try t.expect(!seen.contains(n));
        try seen.put(n, {});
    }
}
